/// Content for a wl_surface. A buffer provides the content for a wl_surface. Buffers are created through factory
/// interfaces such as wl_shm, wp_linux_buffer_params (from the linux-dmabuf protocol extension) or similar.
#[derive(Debug)]
pub struct WlBuffer(Proxy);

impl Object for WlBuffer {
    const INTERFACE: &'static Interface = &WL_BUFFER_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlBuffer(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlBuffer {
    /// Destroy a buffer. Destroy a buffer. If and how you need to release the backing storage is defined by the buffer
    /// factory interface.
    pub fn destroy(self) {
        self.0.destroy_with(0, &[]);
    }
}

/// The `wl_buffer` interface's events.
#[derive(Debug)]
pub enum WlBufferEvent {
    /// Compositor releases buffer. Sent when this wl_buffer is no longer used by the compositor.
    Release,
}

impl WlBufferEvent {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Release,
            _ => return None,
        })
    }
}

