/// The `wl_data_offer` interface's table (libwayland's `wl_interface`).
pub static WL_DATA_OFFER_INTERFACE: Interface =
    Interface::new(c"wl_data_offer", 4, &WL_DATA_OFFER_REQUESTS, &WL_DATA_OFFER_EVENTS, Some(2));

/// Offer to transfer data. A wl_data_offer represents a piece of data offered for transfer by another client (the
/// source client). It is used by the copy-and-paste and drag-and-drop mechanisms.
#[derive(Debug)]
pub struct WlDataOffer(Proxy);

impl Object for WlDataOffer {
    const INTERFACE: &'static Interface = &WL_DATA_OFFER_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlDataOffer(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlDataOffer {
    /// Accept one of the offered mime types. Indicate that the client can accept the given mime type, or NULL for not
    /// accepted.
    ///
    /// - `serial`: serial number of the accept request.
    /// - `mime_type`: mime type accepted by the client.
    pub fn accept(&self, serial: u32, mime_type: Option<&str>) {
        let c_mime_type = mime_type.map(c_string);
        self.0.send(0, &[Arg::Uint(serial), Arg::Str(c_mime_type.as_deref())]);
    }

    /// Request that the data is transferred. To transfer the offered data, the client issues this request and indicates
    /// the mime type it wants to receive. The transfer happens through the passed file descriptor (typically created
    /// with the pipe system call).
    ///
    /// - `mime_type`: mime type desired by receiver.
    /// - `fd`: file descriptor for data transfer.
    pub fn receive(&self, mime_type: &str, fd: BorrowedFd<'_>) {
        let c_mime_type = c_string(mime_type);
        self.0.send(1, &[Arg::Str(Some(&c_mime_type)), Arg::Fd(fd)]);
    }

    /// Destroy data offer. Destroy the data offer.
    pub fn destroy(self) {
        self.0.destroy_with(2, &[]);
    }

    /// The offer will no longer be used. Notifies the compositor that the drag destination successfully finished the
    /// drag-and-drop operation.
    ///
    /// Since version 3.
    /// (Not sent to an object of an older version: what it makes is then none.)
    pub fn finish(&self) {
        self.0.send(3, &[]);
    }

    /// Set the available/preferred drag-and-drop actions. Sets the actions that the destination side client supports
    /// for this operation. This request may trigger the emission of wl_data_source.action and wl_data_offer.action
    /// events if the compositor needs to change the selected action.
    ///
    /// Since version 3.
    /// (Not sent to an object of an older version: what it makes is then none.)
    ///
    /// - `dnd_actions`: actions supported by the destination client.
    /// - `preferred_action`: action preferred by the destination client.
    pub fn set_actions(
        &self,
        dnd_actions: WlDataDeviceManagerDndAction,
        preferred_action: WlDataDeviceManagerDndAction,
    ) {
        self.0.send(4, &[Arg::Uint(dnd_actions.0), Arg::Uint(preferred_action.0)]);
    }
}

/// The `wl_data_offer` interface's events.
#[derive(Debug)]
pub enum WlDataOfferEvent {
    /// Advertise offered mime type. Sent immediately after creating the wl_data_offer object. One event per offered
    /// mime type.
    Offer {
        /// Offered mime type.
        mime_type: String,
    },
    /// Notify the source-side available actions. This event indicates the actions offered by the data source. It will
    /// be sent immediately after creating the wl_data_offer object, or anytime the source side changes its offered
    /// actions through wl_data_source.set_actions.
    ///
    /// Since version 3.
    SourceActions {
        /// Actions offered by the data source.
        source_actions: WlDataDeviceManagerDndAction,
    },
    /// Notify the selected action. This event indicates the action selected by the compositor after matching the
    /// source/destination side actions. Only one action (or none) will be offered here.
    ///
    /// Since version 3.
    Action {
        /// Action selected by the compositor.
        dnd_action: WlDataDeviceManagerDndAction,
    },
}

impl WlDataOfferEvent {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Offer { mime_type: args.string()? },
            1 => Self::SourceActions { source_actions: WlDataDeviceManagerDndAction(args.uint()?) },
            2 => Self::Action { dnd_action: WlDataDeviceManagerDndAction(args.uint()?) },
            _ => return None,
        })
    }
}

/// `wl_data_offer.error`'s values.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub struct WlDataOfferError(pub u32);

impl WlDataOfferError {
    /// Finish request was called untimely.
    pub const INVALID_FINISH: Self = Self(0);
    /// Action mask contains invalid values.
    pub const INVALID_ACTION_MASK: Self = Self(1);
    /// Action argument has an invalid value.
    pub const INVALID_ACTION: Self = Self(2);
    /// Offer doesn't accept this request.
    pub const INVALID_OFFER: Self = Self(3);
}

