/// Offer to transfer data. The wl_data_source object is the source side of a wl_data_offer. It is created by the source
/// client in a data transfer and provides a way to describe the offered data and a way to respond to requests to
/// transfer the data.
#[derive(Debug)]
pub struct WlDataSource(Proxy);

impl Object for WlDataSource {
    const INTERFACE: &'static Interface = &WL_DATA_SOURCE_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlDataSource(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlDataSource {
    /// Add an offered mime type. This request adds a mime type to the set of mime types advertised to targets. Can be
    /// called several times to offer multiple types.
    ///
    /// - `mime_type`: mime type offered by the data source.
    pub fn offer(&self, mime_type: &str) {
        let c_mime_type = c_string(mime_type);
        self.0.send(0, &[Arg::Str(Some(&c_mime_type))]);
    }

    /// Destroy the data source.
    pub fn destroy(self) {
        self.0.destroy_with(1, &[]);
    }

    /// Set the available drag-and-drop actions. Sets the actions that the source side client supports for this
    /// operation. This request may trigger wl_data_source.action and wl_data_offer.action events if the compositor
    /// needs to change the selected action.
    ///
    /// Since version 3.
    /// (Not sent to an object of an older version: what it makes is then none.)
    ///
    /// - `dnd_actions`: actions supported by the data source.
    pub fn set_actions(&self, dnd_actions: WlDataDeviceManagerDndAction) {
        self.0.send(2, &[Arg::Uint(dnd_actions.0)]);
    }
}

/// The `wl_data_source` interface's events.
#[derive(Debug)]
pub enum WlDataSourceEvent {
    /// A target accepts an offered mime type. Sent when a target accepts pointer_focus or motion events. If a target
    /// does not accept any of the offered types, type is NULL.
    Target {
        /// Mime type accepted by the target.
        mime_type: Option<String>,
    },
    /// Send the data. Request for data from the client. Send the data as the specified mime type over the passed file
    /// descriptor, then close it.
    Send {
        /// Mime type for the data.
        mime_type: String,
        /// File descriptor for the data.
        fd: OwnedFd,
    },
    /// Selection was cancelled. This data source is no longer valid. There are several reasons why this could happen:
    Cancelled,
    /// The drag-and-drop operation physically finished. The user performed the drop action. This event does not
    /// indicate acceptance, wl_data_source.cancelled may still be emitted afterwards if the drop destination does not
    /// accept any mime type.
    ///
    /// Since version 3.
    DndDropPerformed,
    /// The drag-and-drop operation concluded. The drop destination finished interoperating with this data source, so
    /// the client is now free to destroy this data source and free all associated data.
    ///
    /// Since version 3.
    DndFinished,
    /// Notify the selected action. This event indicates the action selected by the compositor after matching the
    /// source/destination side actions. Only one action (or none) will be offered here.
    ///
    /// Since version 3.
    Action {
        /// Action selected by the compositor.
        dnd_action: WlDataDeviceManagerDndAction,
    },
}

impl WlDataSourceEvent {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Target { mime_type: args.opt_string()? },
            1 => Self::Send { mime_type: args.string()?, fd: args.fd()? },
            2 => Self::Cancelled,
            3 => Self::DndDropPerformed,
            4 => Self::DndFinished,
            5 => Self::Action { dnd_action: WlDataDeviceManagerDndAction(args.uint()?) },
            _ => return None,
        })
    }
}

