/// Data transfer device. There is one wl_data_device per seat which can be obtained from the global
/// wl_data_device_manager singleton.
#[derive(Debug)]
pub struct WlDataDevice(Proxy);

impl Object for WlDataDevice {
    const INTERFACE: &'static Interface = &WL_DATA_DEVICE_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlDataDevice(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlDataDevice {
    /// Start drag-and-drop operation. This request asks the compositor to start a drag-and-drop operation on behalf of
    /// the client.
    ///
    /// - `source`: data source for the eventual transfer.
    /// - `origin`: surface where the drag originates.
    /// - `icon`: drag-and-drop icon surface.
    /// - `serial`: serial number of the implicit grab on the origin.
    pub fn start_drag(&self, source: Option<&WlDataSource>, origin: &WlSurface, icon: Option<&WlSurface>, serial: u32) {
        self.0.send(
            0,
            &[
                Arg::Object(source.map(|o| o.proxy())),
                Arg::Object(Some(origin.proxy())),
                Arg::Object(icon.map(|o| o.proxy())),
                Arg::Uint(serial),
            ],
        );
    }

    /// Copy data to the selection. This request asks the compositor to set the selection to the data from the source on
    /// behalf of the client.
    ///
    /// - `source`: data source for the selection.
    /// - `serial`: serial number of the event that triggered this request.
    pub fn set_selection(&self, source: Option<&WlDataSource>, serial: u32) {
        self.0.send(1, &[Arg::Object(source.map(|o| o.proxy())), Arg::Uint(serial)]);
    }

    /// Destroy data device. This request destroys the data device.
    ///
    /// Since version 2.
    /// (Not sent to an object of an older version: what it makes is then none.)
    pub fn release(self) {
        self.0.destroy_with(2, &[]);
    }
}

/// The `wl_data_device` interface's events.
#[derive(Debug)]
pub enum WlDataDeviceEvent {
    /// Introduce a new wl_data_offer. The data_offer event introduces a new wl_data_offer object, which will
    /// subsequently be used in either the data_device.enter event (for drag-and-drop) or the data_device.selection
    /// event (for selections). Immediately following the data_device.data_offer event, the new data_offer object will
    /// send out data_offer.offer events to describe the mime types it offers.
    DataOffer {
        /// The new data_offer object.
        id: WlDataOffer,
    },
    /// Initiate drag-and-drop session. This event is sent when an active drag-and-drop pointer enters a surface owned
    /// by the client. The position of the pointer at enter time is provided by the x and y arguments, in surface-local
    /// coordinates.
    Enter {
        /// Serial number of the enter event.
        serial: u32,
        /// Client surface entered.
        surface: ObjectId,
        /// Surface-local x coordinate.
        x: f64,
        /// Surface-local y coordinate.
        y: f64,
        /// Source data_offer object.
        id: Option<ObjectId>,
    },
    /// End drag-and-drop session. This event is sent when the drag-and-drop pointer leaves the surface and the session
    /// ends. The client must destroy the wl_data_offer introduced at enter time at this point.
    Leave,
    /// Drag-and-drop session motion. This event is sent when the drag-and-drop pointer moves within the currently
    /// focused surface. The new position of the pointer is provided by the x and y arguments, in surface-local
    /// coordinates.
    Motion {
        /// Timestamp with millisecond granularity.
        time: u32,
        /// Surface-local x coordinate.
        x: f64,
        /// Surface-local y coordinate.
        y: f64,
    },
    /// End drag-and-drop session successfully. The event is sent when a drag-and-drop operation is ended because the
    /// implicit grab is removed.
    Drop,
    /// Advertise new selection. The selection event is sent out to notify the client of a new wl_data_offer for the
    /// selection for this device. The data_device.data_offer and the data_offer.offer events are sent out immediately
    /// before this event to introduce the data offer object.
    Selection {
        /// Selection data_offer object.
        id: Option<ObjectId>,
    },
}

impl WlDataDeviceEvent {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::DataOffer { id: args.new_id()? },
            1 => Self::Enter {
                serial: args.uint()?,
                surface: args.object()?,
                x: args.fixed()?,
                y: args.fixed()?,
                id: args.opt_object()?,
            },
            2 => Self::Leave,
            3 => Self::Motion { time: args.uint()?, x: args.fixed()?, y: args.fixed()? },
            4 => Self::Drop,
            5 => Self::Selection { id: args.opt_object()? },
            _ => return None,
        })
    }
}

