/// Data transfer interface. The wl_data_device_manager is a singleton global object that provides access to
/// inter-client data transfer mechanisms such as copy-and-paste and drag-and-drop. These mechanisms are tied to a
/// wl_seat and this interface lets a client get a wl_data_device corresponding to a wl_seat.
#[derive(Debug)]
pub struct WlDataDeviceManager(Proxy);

impl Object for WlDataDeviceManager {
    const INTERFACE: &'static Interface = &WL_DATA_DEVICE_MANAGER_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlDataDeviceManager(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlDataDeviceManager {
    /// Create a new data source.
    #[must_use = "the object made is destroyed when dropped"]
    pub fn create_data_source(&self) -> Option<WlDataSource> {
        self.0.create(0, &[Arg::NewId])
    }

    /// Create a new data device. Create a new data device for a given seat.
    ///
    /// - `seat`: seat associated with the data device.
    #[must_use = "the object made is destroyed when dropped"]
    pub fn get_data_device(&self, seat: &WlSeat) -> Option<WlDataDevice> {
        self.0.create(1, &[Arg::NewId, Arg::Object(Some(seat.proxy()))])
    }

    /// Destroy wl_data_device_manager. This request destroys the wl_data_device_manager. This has no effect on any
    /// other objects.
    ///
    /// Since version 4.
    /// (Not sent to an object of an older version: what it makes is then none.)
    pub fn release(self) {
        self.0.destroy_with(2, &[]);
    }
}

