/// Desktop-style metadata interface. An interface that may be implemented by a wl_surface, for implementations that
/// provide a desktop-style user interface.
#[derive(Debug)]
pub struct WlShellSurface(Proxy);

impl Object for WlShellSurface {
    const INTERFACE: &'static Interface = &WL_SHELL_SURFACE_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlShellSurface(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlShellSurface {
    /// Respond to a ping event. A client must respond to a ping event with a pong request or the client may be deemed
    /// unresponsive.
    ///
    /// - `serial`: serial number of the ping event.
    pub fn pong(&self, serial: u32) {
        self.0.send(0, &[Arg::Uint(serial)]);
    }

    /// Start an interactive move. Start a pointer-driven move of the surface.
    ///
    /// - `seat`: seat whose pointer is used.
    /// - `serial`: serial number of the implicit grab on the pointer.
    pub fn r#move(&self, seat: &WlSeat, serial: u32) {
        self.0.send(1, &[Arg::Object(Some(seat.proxy())), Arg::Uint(serial)]);
    }

    /// Start an interactive resize. Start a pointer-driven resizing of the surface.
    ///
    /// - `seat`: seat whose pointer is used.
    /// - `serial`: serial number of the implicit grab on the pointer.
    /// - `edges`: which edge or corner is being dragged.
    pub fn resize(&self, seat: &WlSeat, serial: u32, edges: WlShellSurfaceResize) {
        self.0.send(2, &[Arg::Object(Some(seat.proxy())), Arg::Uint(serial), Arg::Uint(edges.0)]);
    }

    /// Make the surface a toplevel surface. Map the surface as a toplevel surface.
    pub fn set_toplevel(&self) {
        self.0.send(3, &[]);
    }

    /// Make the surface a transient surface. Map the surface relative to an existing surface.
    ///
    /// - `parent`: parent surface.
    /// - `x`: surface-local x coordinate.
    /// - `y`: surface-local y coordinate.
    /// - `flags`: transient surface behavior.
    pub fn set_transient(&self, parent: &WlSurface, x: i32, y: i32, flags: WlShellSurfaceTransient) {
        self.0.send(4, &[Arg::Object(Some(parent.proxy())), Arg::Int(x), Arg::Int(y), Arg::Uint(flags.0)]);
    }

    /// Make the surface a fullscreen surface. Map the surface as a fullscreen surface.
    ///
    /// - `method`: method for resolving size conflict.
    /// - `framerate`: framerate in mHz.
    /// - `output`: output on which the surface is to be fullscreen.
    pub fn set_fullscreen(&self, method: WlShellSurfaceFullscreenMethod, framerate: u32, output: Option<&WlOutput>) {
        self.0.send(5, &[Arg::Uint(method.0), Arg::Uint(framerate), Arg::Object(output.map(|o| o.proxy()))]);
    }

    /// Make the surface a popup surface. Map the surface as a popup.
    ///
    /// - `seat`: seat whose pointer is used.
    /// - `serial`: serial number of the implicit grab on the pointer.
    /// - `parent`: parent surface.
    /// - `x`: surface-local x coordinate.
    /// - `y`: surface-local y coordinate.
    /// - `flags`: transient surface behavior.
    pub fn set_popup(
        &self,
        seat: &WlSeat,
        serial: u32,
        parent: &WlSurface,
        x: i32,
        y: i32,
        flags: WlShellSurfaceTransient,
    ) {
        self.0.send(
            6,
            &[
                Arg::Object(Some(seat.proxy())),
                Arg::Uint(serial),
                Arg::Object(Some(parent.proxy())),
                Arg::Int(x),
                Arg::Int(y),
                Arg::Uint(flags.0),
            ],
        );
    }

    /// Make the surface a maximized surface. Map the surface as a maximized surface.
    ///
    /// - `output`: output on which the surface is to be maximized.
    pub fn set_maximized(&self, output: Option<&WlOutput>) {
        self.0.send(7, &[Arg::Object(output.map(|o| o.proxy()))]);
    }

    /// Set surface title. Set a short title for the surface.
    ///
    /// - `title`: surface title.
    pub fn set_title(&self, title: &str) {
        let c_title = c_string(title);
        self.0.send(8, &[Arg::Str(Some(&c_title))]);
    }

    /// Set surface class. Set a class for the surface.
    ///
    /// - `class_`: surface class.
    pub fn set_class(&self, class_: &str) {
        let c_class_ = c_string(class_);
        self.0.send(9, &[Arg::Str(Some(&c_class_))]);
    }
}

/// The `wl_shell_surface` interface's events.
#[derive(Debug)]
pub enum WlShellSurfaceEvent {
    /// Ping client. Ping a client to check if it is receiving events and sending requests. A client is expected to
    /// reply with a pong request.
    Ping {
        /// Serial number of the ping.
        serial: u32,
    },
    /// Suggest resize. The configure event asks the client to resize its surface.
    Configure {
        /// How the surface was resized.
        edges: WlShellSurfaceResize,
        /// New width of the surface.
        width: i32,
        /// New height of the surface.
        height: i32,
    },
    /// Popup interaction is done. The popup_done event is sent out when a popup grab is broken, that is, when the user
    /// clicks a surface that doesn't belong to the client owning the popup surface.
    PopupDone,
}

impl WlShellSurfaceEvent {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Ping { serial: args.uint()? },
            1 => Self::Configure { edges: WlShellSurfaceResize(args.uint()?), width: args.int()?, height: args.int()? },
            2 => Self::PopupDone,
            _ => return None,
        })
    }
}

