/// Different method to set the surface fullscreen. Hints to indicate to the compositor how to deal with a conflict
/// between the dimensions of the surface and the dimensions of the output. The compositor is free to ignore this
/// parameter.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub struct WlShellSurfaceFullscreenMethod(pub u32);

impl WlShellSurfaceFullscreenMethod {
    /// No preference, apply default policy.
    pub const DEFAULT: Self = Self(0);
    /// Scale, preserve the surface's aspect ratio and center on output.
    pub const SCALE: Self = Self(1);
    /// Switch output mode to the smallest mode that can fit the surface, add black borders to compensate size mismatch.
    pub const DRIVER: Self = Self(2);
    /// No upscaling, center on output and add black borders to compensate size mismatch.
    pub const FILL: Self = Self(3);
}

