pub static WL_SURFACE_INTERFACE: Interface =
    Interface::new(c"wl_surface", 7, &WL_SURFACE_REQUESTS, &WL_SURFACE_EVENTS, Some(0));

/// An onscreen surface. A surface is a rectangular area that may be displayed on zero or more outputs, and shown any
/// number of times at the compositor's discretion. They can present wl_buffers, receive user input, and define a local
/// coordinate system.
#[derive(Debug)]
pub struct WlSurface(Proxy);

impl Object for WlSurface {
    const INTERFACE: &'static Interface = &WL_SURFACE_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlSurface(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlSurface {
    /// Delete surface. Deletes the surface and invalidates its object ID.
    pub fn destroy(self) {
        self.0.destroy_with(0, &[]);
    }

    /// Set the surface contents. Set a buffer as the content of this surface.
    ///
    /// - `buffer`: buffer of surface contents.
    /// - `x`: surface-local x coordinate.
    /// - `y`: surface-local y coordinate.
    pub fn attach(&self, buffer: Option<&WlBuffer>, x: i32, y: i32) {
        self.0.send(1, &[Arg::Object(buffer.map(|o| o.proxy())), Arg::Int(x), Arg::Int(y)]);
    }

    /// Mark part of the surface damaged. This request is used to describe the regions where the pending buffer is
    /// different from the current surface contents, and where the surface therefore needs to be repainted. The
    /// compositor ignores the parts of the damage that fall outside of the surface.
    ///
    /// - `x`: surface-local x coordinate.
    /// - `y`: surface-local y coordinate.
    /// - `width`: width of damage rectangle.
    /// - `height`: height of damage rectangle.
    pub fn damage(&self, x: i32, y: i32, width: i32, height: i32) {
        self.0.send(2, &[Arg::Int(x), Arg::Int(y), Arg::Int(width), Arg::Int(height)]);
    }

    /// Request a frame throttling hint. Request a notification when it is a good time to start drawing a new frame, by
    /// creating a frame callback. This is useful for throttling redrawing operations, and driving animations.
    #[must_use = "the object made is destroyed when dropped"]
    pub fn frame(&self) -> Option<WlCallback> {
        self.0.create(3, &[Arg::NewId])
    }

    /// Set opaque region. This request sets the region of the surface that contains opaque content.
    ///
    /// - `region`: opaque region of the surface.
    pub fn set_opaque_region(&self, region: Option<&WlRegion>) {
        self.0.send(4, &[Arg::Object(region.map(|o| o.proxy()))]);
    }

    /// Set input region. This request sets the region of the surface that can receive pointer and touch events.
    ///
    /// - `region`: input region of the surface.
    pub fn set_input_region(&self, region: Option<&WlRegion>) {
        self.0.send(5, &[Arg::Object(region.map(|o| o.proxy()))]);
    }

    /// Commit pending surface state. Surface state (input, opaque, and damage regions, attached buffers, etc.) is
    /// double-buffered. Protocol requests modify the pending state, as opposed to the active state in use by the
    /// compositor.
    pub fn commit(&self) {
        self.0.send(6, &[]);
    }

    /// Sets the buffer transformation. This request sets the transformation that the client has already applied to the
    /// content of the buffer. The accepted values for the transform parameter are the values for wl_output.transform.
    ///
    /// Since version 2.
    /// (Not sent to an object of an older version: what it makes is then none.)
    ///
    /// - `transform`: transform for interpreting buffer contents.
    pub fn set_buffer_transform(&self, transform: WlOutputTransform) {
        self.0.send(7, &[Arg::Int(transform.0 as i32)]);
    }

    /// Sets the buffer scaling factor. This request sets an optional scaling factor on how the compositor interprets
    /// the contents of the buffer attached to the window.
    ///
    /// Since version 3.
    /// (Not sent to an object of an older version: what it makes is then none.)
    ///
    /// - `scale`: scale for interpreting buffer contents.
    pub fn set_buffer_scale(&self, scale: i32) {
        self.0.send(8, &[Arg::Int(scale)]);
    }

    /// Mark part of the surface damaged using buffer coordinates. This request is used to describe the regions where
    /// the pending buffer is different from the current surface contents, and where the surface therefore needs to be
    /// repainted. The compositor ignores the parts of the damage that fall outside of the surface.
    ///
    /// Since version 4.
    /// (Not sent to an object of an older version: what it makes is then none.)
    ///
    /// - `x`: buffer-local x coordinate.
    /// - `y`: buffer-local y coordinate.
    /// - `width`: width of damage rectangle.
    /// - `height`: height of damage rectangle.
    pub fn damage_buffer(&self, x: i32, y: i32, width: i32, height: i32) {
        self.0.send(9, &[Arg::Int(x), Arg::Int(y), Arg::Int(width), Arg::Int(height)]);
    }

    /// Set the surface contents offset. The x and y arguments specify the location of the new pending buffer's upper
    /// left corner, relative to the current buffer's upper left corner, in surface-local coordinates. In other words,
    /// the x and y, combined with the new surface size define in which directions the surface's size changes.
    ///
    /// Since version 5.
    /// (Not sent to an object of an older version: what it makes is then none.)
    ///
    /// - `x`: surface-local x coordinate.
    /// - `y`: surface-local y coordinate.
    pub fn offset(&self, x: i32, y: i32) {
        self.0.send(10, &[Arg::Int(x), Arg::Int(y)]);
    }

    /// Get a release callback. Create a callback for the release of the buffer attached by the client with
    /// wl_surface.attach.
    ///
    /// Since version 7.
    /// (Not sent to an object of an older version: what it makes is then none.)
    #[must_use = "the object made is destroyed when dropped"]
    pub fn get_release(&self) -> Option<WlCallback> {
        self.0.create(11, &[Arg::NewId])
    }
}

/// The `wl_surface` interface's events.
#[derive(Debug)]
pub enum WlSurfaceEvent {
    /// Surface enters an output. This is emitted whenever a surface's creation, movement, or resizing results in some
    /// part of it being within the scanout region of an output.
    Enter {
        /// Output entered by the surface.
        output: ObjectId,
    },
    /// Surface leaves an output. This is emitted whenever a surface's creation, movement, or resizing results in it no
    /// longer having any part of it within the scanout region of an output.
    Leave {
        /// Output left by the surface.
        output: ObjectId,
    },
    /// Preferred buffer scale for the surface. This event indicates the preferred buffer scale for this surface. It is
    /// sent whenever the compositor's preference changes.
    ///
    /// Since version 6.
    PreferredBufferScale {
        /// Preferred scaling factor.
        factor: i32,
    },
    /// Preferred buffer transform for the surface. This event indicates the preferred buffer transform for this
    /// surface. It is sent whenever the compositor's preference changes.
    ///
    /// Since version 6.
    PreferredBufferTransform {
        /// Preferred transform.
        transform: WlOutputTransform,
    },
}

impl WlSurfaceEvent {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Enter { output: args.object()? },
            1 => Self::Leave { output: args.object()? },
            2 => Self::PreferredBufferScale { factor: args.int()? },
            3 => Self::PreferredBufferTransform { transform: WlOutputTransform(args.uint()?) },
            _ => return None,
        })
    }
}

/// Wl_surface error values. These errors can be emitted in response to wl_surface requests.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub struct WlSurfaceError(pub u32);

impl WlSurfaceError {
    /// Buffer scale value is invalid.
    pub const INVALID_SCALE: Self = Self(0);
    /// Buffer transform value is invalid.
    pub const INVALID_TRANSFORM: Self = Self(1);
    /// Buffer size is invalid.
    pub const INVALID_SIZE: Self = Self(2);
    /// Buffer offset is invalid.
    pub const INVALID_OFFSET: Self = Self(3);
    /// Surface was destroyed before its role object.
    pub const DEFUNCT_ROLE_OBJECT: Self = Self(4);
    /// No buffer was attached.
    pub const NO_BUFFER: Self = Self(5);
}

