/// Group of input devices. A seat is a group of keyboards, pointer and touch devices. This object is published as a
/// global during start up, or when such a device is hot plugged.
#[derive(Debug)]
pub struct WlSeat(Proxy);

impl Object for WlSeat {
    const INTERFACE: &'static Interface = &WL_SEAT_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlSeat(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlSeat {
    /// Return pointer object. The ID provided will be initialized to the wl_pointer interface for this seat.
    #[must_use = "the object made is destroyed when dropped"]
    pub fn get_pointer(&self) -> Option<WlPointer> {
        self.0.create(0, &[Arg::NewId])
    }

    /// Return keyboard object. The ID provided will be initialized to the wl_keyboard interface for this seat.
    #[must_use = "the object made is destroyed when dropped"]
    pub fn get_keyboard(&self) -> Option<WlKeyboard> {
        self.0.create(1, &[Arg::NewId])
    }

    /// Return touch object. The ID provided will be initialized to the wl_touch interface for this seat.
    #[must_use = "the object made is destroyed when dropped"]
    pub fn get_touch(&self) -> Option<WlTouch> {
        self.0.create(2, &[Arg::NewId])
    }

    /// Release the seat object. Using this request a client can tell the server that it is not going to use the seat
    /// object anymore.
    ///
    /// Since version 5.
    /// (Not sent to an object of an older version: what it makes is then none.)
    pub fn release(self) {
        self.0.destroy_with(3, &[]);
    }
}

/// The `wl_seat` interface's events.
#[derive(Debug)]
pub enum WlSeatEvent {
    /// Seat capabilities changed. This is sent on binding to the seat global or whenever a seat gains or loses the
    /// pointer, keyboard or touch capabilities. The argument is a capability enum containing the complete set of
    /// capabilities this seat has.
    Capabilities {
        /// Capabilities of the seat.
        capabilities: WlSeatCapability,
    },
    /// Unique identifier for this seat. In a multi-seat configuration the seat name can be used by clients to help
    /// identify which physical devices the seat represents.
    ///
    /// Since version 2.
    Name {
        /// Seat identifier.
        name: String,
    },
}

impl WlSeatEvent {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Capabilities { capabilities: WlSeatCapability(args.uint()?) },
            1 => Self::Name { name: args.string()? },
            _ => return None,
        })
    }
}

