/// Pointer input device. The wl_pointer interface represents one or more input devices, such as mice, which control the
/// pointer location and pointer_focus of a seat.
#[derive(Debug)]
pub struct WlPointer(Proxy);

impl Object for WlPointer {
    const INTERFACE: &'static Interface = &WL_POINTER_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlPointer(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlPointer {
    /// Set the pointer surface. Set the pointer surface, i.e., the surface that contains the pointer image (cursor).
    /// This request gives the surface the role of a cursor.
    ///
    /// - `serial`: serial number of the enter event.
    /// - `surface`: pointer surface.
    /// - `hotspot_x`: surface-local x coordinate.
    /// - `hotspot_y`: surface-local y coordinate.
    pub fn set_cursor(&self, serial: u32, surface: Option<&WlSurface>, hotspot_x: i32, hotspot_y: i32) {
        self.0.send(
            0,
            &[Arg::Uint(serial), Arg::Object(surface.map(|o| o.proxy())), Arg::Int(hotspot_x), Arg::Int(hotspot_y)],
        );
    }

    /// Release the pointer object. Using this request a client can tell the server that it is not going to use the
    /// pointer object anymore.
    ///
    /// Since version 3.
    /// (Not sent to an object of an older version: what it makes is then none.)
    pub fn release(self) {
        self.0.destroy_with(1, &[]);
    }
}

/// The `wl_pointer` interface's events.
