    Interface::new(c"wl_subsurface", 1, &WL_SUBSURFACE_REQUESTS, &WL_SUBSURFACE_EVENTS, Some(0));

/// Sub-surface interface to a wl_surface. An additional interface to a wl_surface object, which has been made a
/// sub-surface. A sub-surface has one parent surface.
#[derive(Debug)]
pub struct WlSubsurface(Proxy);

impl Object for WlSubsurface {
    const INTERFACE: &'static Interface = &WL_SUBSURFACE_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlSubsurface(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlSubsurface {
    /// Remove sub-surface interface. The sub-surface interface is removed from the wl_surface object that was turned
    /// into a sub-surface with a wl_subcompositor.get_subsurface request. The wl_surface's association to the parent is
    /// deleted.
    pub fn destroy(self) {
        self.0.destroy_with(0, &[]);
    }

    /// Reposition the sub-surface. This sets the position of the sub-surface, relative to the parent surface.
    ///
    /// - `x`: x coordinate in the parent surface.
    /// - `y`: y coordinate in the parent surface.
    pub fn set_position(&self, x: i32, y: i32) {
        self.0.send(1, &[Arg::Int(x), Arg::Int(y)]);
    }

    /// Restack the sub-surface. This sub-surface is taken from the stack, and put back just above the reference
    /// surface, changing the z-order of the sub-surfaces. The reference surface must be one of the sibling surfaces, or
    /// the parent surface.
    ///
    /// - `sibling`: the reference surface.
    pub fn place_above(&self, sibling: &WlSurface) {
        self.0.send(2, &[Arg::Object(Some(sibling.proxy()))]);
    }

    /// Restack the sub-surface. The sub-surface is placed just below the reference surface.
    ///
    /// - `sibling`: the reference surface.
    pub fn place_below(&self, sibling: &WlSurface) {
        self.0.send(3, &[Arg::Object(Some(sibling.proxy()))]);
    }

    /// Set sub-surface to synchronized mode. Change the commit behaviour of the sub-surface to synchronized mode.
    pub fn set_sync(&self) {
        self.0.send(4, &[]);
    }

    /// Set sub-surface to desynchronized mode. Change the commit behaviour of the sub-surface to desynchronized mode.
    pub fn set_desync(&self) {
        self.0.send(5, &[]);
    }
}

/// `wl_subsurface.error`'s values.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub struct WlSubsurfaceError(pub u32);

impl WlSubsurfaceError {
    /// Wl_surface is not a sibling or the parent.
    pub const BAD_SURFACE: Self = Self(0);
}

