/// Wayland protocol fixes. This global fixes problems with other core-protocol interfaces that cannot be fixed in these
/// interfaces themselves.
#[derive(Debug)]
pub struct WlFixes(Proxy);

impl Object for WlFixes {
    const INTERFACE: &'static Interface = &WL_FIXES_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        WlFixes(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl WlFixes {
    /// Destroys this object.
    pub fn destroy(self) {
        self.0.destroy_with(0, &[]);
    }

    /// Destroy a wl_registry. This request destroys a wl_registry object.
    ///
    /// - `registry`: the registry to destroy.
    pub fn destroy_registry(&self, registry: &WlRegistry) {
        self.0.send(1, &[Arg::Object(Some(registry.proxy()))]);
    }

    /// Acknowledge global removal. Acknowledge the removal of the specified global.
    ///
    /// Since version 2.
    /// (Not sent to an object of an older version: what it makes is then none.)
    ///
    /// - `registry`: the registry object.
    /// - `name`: unique name of the global.
    pub fn ack_global_remove(&self, registry: &WlRegistry, name: u32) {
        self.0.send(2, &[Arg::Object(Some(registry.proxy())), Arg::Uint(name)]);
    }
}

/// Wl_fixes error values. These errors can be emitted in response to wl_fixes requests.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub struct WlFixesError(pub u32);

impl WlFixesError {
    /// Unknown global or the global is not removed.
    pub const INVALID_ACK_REMOVE: Self = Self(0);
}
